                ["pass-asc", "Pass rate"],
              ] as const
            ).map(([id, label]) => (
              <button
                key={id}
                type="button"
                onClick={() => setSortMode(id)}
                className={`rounded-md px-2.5 py-1.5 text-sm font-medium transition ${
                  sortMode === id
                    ? "bg-rose-900 text-white"
                    : "bg-slate-100 text-slate-700 hover:bg-slate-200"
                }`}
              >
                {label}
              </button>
            ))}
          </>
        )}
      </div>

      <div className="mb-2">
        <h4 className="text-base font-semibold text-slate-900">{meta.title}</h4>
        <p className="text-sm text-slate-600">{meta.subtitle}</p>
      </div>

      <div className="h-[380px] w-full sm:h-[420px]">
        {panel === "age-bands" && (
          <ResponsiveContainer width="100%" height="100%">
            <BarChart
              data={NATIONAL_AGE_BANDS}
              layout="vertical"
              margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.grid} />
              <XAxis type="number" tick={{ fontSize: 11 }} unit="%" />
              <YAxis
                type="category"
                dataKey="band"
                width={56}
                tick={{ fontSize: 11 }}
              />
              <Tooltip
                formatter={(v, name) => [
                  `${v}%`,
                  name === "electricianPct" ? "Electricians" : "Plumbers",
                ]}
              />
              <Legend />
              <Bar
                dataKey="electricianPct"
                name="Electricians"
                fill={COLORS.electrician}
                radius={[0, 3, 3, 0]}
              />
              <Bar
                dataKey="plumberPct"
                name="Plumbers"
                fill={COLORS.plumber}
                radius={[0, 3, 3, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        )}

        {panel === "state-ladder" && (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart
              data={ladderData}
              layout="vertical"
              margin={{ top: 8, right: 24, left: 8, bottom: 8 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.grid} />
              <XAxis
                type="number"
                tick={{ fontSize: 11 }}
                domain={[0, 32]}
                unit="%"
              />
              <YAxis
                type="category"
                dataKey="label"
                width={36}
                tick={{ fontSize: 11 }}
              />
              <Tooltip
                formatter={(v, name) => {
                  if (name === "share55") return [`${v}%`, "Share 55+"];
                  if (name === "pass") return [`${v}%`, "Exam pass"];
                  return [v, String(name)];
                }}
              />
              <Legend />
              <Bar dataKey="share55" name="Share 55+" radius={[0, 3, 3, 0]}>
                {ladderData.map((d) => (
                  <Cell
                    key={d.label}
                    fill={REGION_COLOR[d.region] ?? tradeColor}
                  />
                ))}
              </Bar>
              <Line
                type="monotone"
                dataKey="pass"
                name="Exam pass %"
                stroke={COLORS.accent}
                strokeWidth={2}
                dot={{ r: 3 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        )}

        {panel === "pipeline-scatter" && (
          <ResponsiveContainer width="100%" height="100%">
            <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 12 }}>
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.grid} />
              <XAxis
                type="number"
                dataKey="share55"
                name="Share 55+"
                unit="%"
                tick={{ fontSize: 11 }}
                domain={[10, 30]}
                label={{
                  value: "Share 55+ (%)",
                  position: "insideBottom",
                  offset: -4,
                  fontSize: 11,
                }}
              />
              <YAxis
                type="number"
                dataKey="pipelinePressure"
                name="Pressure"
                tick={{ fontSize: 11 }}
                domain={[0, 12]}
                label={{
                  value: "55+ per new license",
                  angle: -90,
                  position: "insideLeft",
                  fontSize: 11,
                }}
              />
              <ZAxis type="number" dataKey="z" range={[40, 280]} />
              <Tooltip
                cursor={{ strokeDasharray: "3 3" }}
                formatter={(v, name) => {
                  if (name === "share55") return [`${v}%`, "Share 55+"];
                  if (name === "pipelinePressure")
                    return [v, "Pipeline pressure"];
                  if (name === "examPassRate") return [`${v}%`, "Exam pass"];
                  return [v, String(name)];
                }}
                labelFormatter={(_, payload) => {
                  const p = payload?.[0]?.payload as
                    | { state?: string; abbr?: string }
                    | undefined;
                  return p?.state ? `${p.state} (${p.abbr})` : "";
                }}
              />
              <Scatter name="States" data={scatterData} fill={tradeColor}>
                {scatterData.map((d) => (
                  <Cell
                    key={`${d.abbr}-${d.trade}`}
                    fill={REGION_COLOR[d.region]}
                    fillOpacity={0.85}
                  />
                ))}
              </Scatter>
            </ScatterChart>
          </ResponsiveContainer>
        )}

        {panel === "license-path" && (
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart
              data={[...LICENSE_TREND]}
              margin={{ top: 12, right: 16, left: 8, bottom: 8 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.grid} />
              <XAxis dataKey="year" tick={{ fontSize: 11 }} />
              <YAxis
                tick={{ fontSize: 11 }}
                tickFormatter={(v) => `${Math.round(Number(v) / 1000)}k`}
              />
              <Tooltip
                formatter={(v, name) => [
                  Number(v).toLocaleString(),
                  name === "electrician"
                    ? "Electrician licenses"
                    : "Plumber licenses",
                ]}
              />
              <Legend />
              <Area
                type="monotone"
                dataKey="electrician"
                name="Electrician"
                stroke={COLORS.electrician}
                fill={COLORS.electrician}
                fillOpacity={0.25}
                strokeWidth={2}
              />
              <Area
                type="monotone"
                dataKey="plumber"
                name="Plumber"
                stroke={COLORS.plumber}
                fill={COLORS.plumber}
                fillOpacity={0.25}
                strokeWidth={2}
              />
            </AreaChart>
          </ResponsiveContainer>
        )}

        {panel === "region-compare" && (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart
              data={regionCompare}
              margin={{ top: 12, right: 16, left: 8, bottom: 8 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.grid} />
              <XAxis dataKey="region" tick={{ fontSize: 12 }} />
              <YAxis
                yAxisId="left"
                tick={{ fontSize: 11 }}
                unit="%"
                domain={[0, 30]}
              />
              <YAxis
                yAxisId="right"
                orientation="right"
                tick={{ fontSize: 11 }}
                unit="%"
                domain={[40, 80]}
              />
              <Tooltip />
              <Legend />
              <Bar
                yAxisId="left"
                dataKey="share55"
                name="Share 55+"
                fill={tradeColor}
                radius={[4, 4, 0, 0]}
              />
              <Line
                yAxisId="right"
                type="monotone"
                dataKey="passRate"
                name="Exam pass %"
                stroke={COLORS.accent}
                strokeWidth={2.5}
                dot={{ r: 4 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        )}
      </div>

      <p className="mt-3 text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

