"use client";

import { useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import {
  ANALYTICS,
  HEADLINE,
  LICENSE_TREND,
  NATIONAL_AGE_BANDS,
  REGION_ROLLUP,
  SOURCE_NOTE,
  STATE_COHORTS,
  type Region,
  type TradeId,
