          </ResponsiveContainer>
        )}

        {panel === "region-compare" && (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart
              data={regionCompare}
              margin={{ top: 12, right: 16, left: 8, bottom: 8 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.grid} />
              <XAxis dataKey="region" tick={{ fontSize: 12 }} />
              <YAxis
                yAxisId="left"
                tick={{ fontSize: 11 }}
                unit="%"
                domain={[0, 30]}
              />
              <YAxis
                yAxisId="right"
                orientation="right"
                tick={{ fontSize: 11 }}
                unit="%"
                domain={[40, 80]}
              />
              <Tooltip />
              <Legend />
              <Bar
                yAxisId="left"
                dataKey="share55"
                name="Share 55+"
                fill={tradeColor}
                radius={[4, 4, 0, 0]}
              />
              <Line
                yAxisId="right"
                type="monotone"
                dataKey="passRate"
                name="Exam pass %"
                stroke={COLORS.accent}
                strokeWidth={2.5}
                dot={{ r: 4 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        )}
      </div>

      <p className="mt-3 text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
