              <Legend />
              <Bar
                dataKey="electricianPct"
                name="Electricians"
                fill={COLORS.electrician}
                radius={[0, 3, 3, 0]}
              />
              <Bar
                dataKey="plumberPct"
                name="Plumbers"
                fill={COLORS.plumber}
                radius={[0, 3, 3, 0]}
              />
            </BarChart>
          </ResponsiveContainer>
        )}

        {panel === "state-ladder" && (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart
