                dataKey="plumber"
                name="Plumber"
                stroke={COLORS.plumber}
                fill={COLORS.plumber}
                fillOpacity={0.25}
                strokeWidth={2}
              />
            </AreaChart>
          </ResponsiveContainer>
        )}

