  electrician: "#0f766e",
  plumber: "#b45309",
  accent: "#ea580c",
  grid: "#e2e8f0",
  northeast: "#1e3a5f",
  midwest: "#0f766e",
  south: "#c2410c",
  west: "#7c3aed",
};

const REGION_COLOR: Record<Region, string> = {
  Northeast: COLORS.northeast,
  Midwest: COLORS.midwest,
  South: COLORS.south,
  West: COLORS.west,
};

