                    key={`${d.abbr}-${d.trade}`}
                    fill={REGION_COLOR[d.region]}
                    fillOpacity={0.85}
                  />
                ))}
              </Scatter>
            </ScatterChart>
          </ResponsiveContainer>
        )}

        {panel === "license-path" && (
          <ResponsiveContainer width="100%" height="100%">
            <AreaChart
              data={[...LICENSE_TREND]}
              margin={{ top: 12, right: 16, left: 8, bottom: 8 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.grid} />
              <XAxis dataKey="year" tick={{ fontSize: 11 }} />
              <YAxis
                tick={{ fontSize: 11 }}
                tickFormatter={(v) => `${Math.round(Number(v) / 1000)}k`}
              />
              <Tooltip
                formatter={(v, name) => [
                  Number(v).toLocaleString(),
                  name === "electrician"
                    ? "Electrician licenses"
                    : "Plumber licenses",
                ]}
              />
              <Legend />
              <Area
                type="monotone"
                dataKey="electrician"
                name="Electrician"
                stroke={COLORS.electrician}
                fill={COLORS.electrician}
                fillOpacity={0.25}
                strokeWidth={2}
              />
              <Area
                type="monotone"
                dataKey="plumber"
                name="Plumber"
                stroke={COLORS.plumber}
                fill={COLORS.plumber}
                fillOpacity={0.25}
                strokeWidth={2}
              />
            </AreaChart>
          </ResponsiveContainer>
        )}

        {panel === "region-compare" && (
          <ResponsiveContainer width="100%" height="100%">
            <ComposedChart
              data={regionCompare}
              margin={{ top: 12, right: 16, left: 8, bottom: 8 }}
            >
              <CartesianGrid strokeDasharray="3 3" stroke={COLORS.grid} />
              <XAxis dataKey="region" tick={{ fontSize: 12 }} />
              <YAxis
                yAxisId="left"
                tick={{ fontSize: 11 }}
                unit="%"
                domain={[0, 30]}
              />
              <YAxis
                yAxisId="right"
                orientation="right"
                tick={{ fontSize: 11 }}
                unit="%"
                domain={[40, 80]}
              />
              <Tooltip />
              <Legend />
              <Bar
                yAxisId="left"
                dataKey="share55"
                name="Share 55+"
                fill={tradeColor}
                radius={[4, 4, 0, 0]}
              />
              <Line
                yAxisId="right"
                type="monotone"
                dataKey="passRate"
                name="Exam pass %"
                stroke={COLORS.accent}
                strokeWidth={2.5}
                dot={{ r: 4 }}
              />
            </ComposedChart>
          </ResponsiveContainer>
        )}
      </div>

      <p className="mt-3 text-xs leading-relaxed text-slate-500">{SOURCE_NOTE}</p>
    </div>
  );
}

